CREATE DATABASE IF NOT EXISTS campus_repair DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE campus_repair;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS order_status_log, evaluation_record, acceptance_record, repair_record, dispatch_record, repair_image, repair_order, repair_location, repair_type, sys_user_role, sys_role, sys_user;
CREATE TABLE sys_user (user_id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '用户主键', username VARCHAR(64) NOT NULL UNIQUE COMMENT '登录名', password_hash VARCHAR(255) NOT NULL COMMENT '密码哈希', real_name VARCHAR(64) NOT NULL COMMENT '真实姓名', phone VARCHAR(32) COMMENT '联系电话', status TINYINT NOT NULL DEFAULT 1 COMMENT '状态', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户表';
CREATE TABLE sys_role (role_id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '角色主键', role_name VARCHAR(64) NOT NULL COMMENT '角色名称', role_code VARCHAR(64) NOT NULL UNIQUE COMMENT '角色编码', remark VARCHAR(255) COMMENT '备注') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色表';
CREATE TABLE sys_user_role (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, assign_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_user_role(user_id,role_id), CONSTRAINT fk_ur_user FOREIGN KEY(user_id) REFERENCES sys_user(user_id), CONSTRAINT fk_ur_role FOREIGN KEY(role_id) REFERENCES sys_role(role_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户角色关联表';
CREATE TABLE repair_type (type_id BIGINT PRIMARY KEY AUTO_INCREMENT, type_name VARCHAR(64) NOT NULL, type_code VARCHAR(64) NOT NULL UNIQUE, description VARCHAR(255), status TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报修类型表';
CREATE TABLE repair_location (location_id BIGINT PRIMARY KEY AUTO_INCREMENT, building_name VARCHAR(128) NOT NULL, area_name VARCHAR(128), room_no VARCHAR(64), description VARCHAR(255), status TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报修地点表';
CREATE TABLE repair_order (order_id BIGINT PRIMARY KEY AUTO_INCREMENT, reporter_id BIGINT NOT NULL, type_id BIGINT NOT NULL, location_id BIGINT NOT NULL, title VARCHAR(128) NOT NULL, description TEXT NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'SUBMITTED', submit_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_order_reporter(reporter_id), KEY idx_order_type(type_id), KEY idx_order_location(location_id), CONSTRAINT fk_order_reporter FOREIGN KEY(reporter_id) REFERENCES sys_user(user_id), CONSTRAINT fk_order_type FOREIGN KEY(type_id) REFERENCES repair_type(type_id), CONSTRAINT fk_order_location FOREIGN KEY(location_id) REFERENCES repair_location(location_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报修工单表';
CREATE TABLE repair_image (image_id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, file_url VARCHAR(500) NOT NULL, file_name VARCHAR(255), upload_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_image_order(order_id), CONSTRAINT fk_image_order FOREIGN KEY(order_id) REFERENCES repair_order(order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报修图片表';
CREATE TABLE dispatch_record (dispatch_id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, admin_id BIGINT NOT NULL, maintainer_id BIGINT NOT NULL, dispatch_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, dispatch_note VARCHAR(255), dispatch_status VARCHAR(32) NOT NULL DEFAULT 'ASSIGNED', KEY idx_dispatch_order(order_id), KEY idx_dispatch_maintainer(maintainer_id), CONSTRAINT fk_dispatch_order FOREIGN KEY(order_id) REFERENCES repair_order(order_id), CONSTRAINT fk_dispatch_admin FOREIGN KEY(admin_id) REFERENCES sys_user(user_id), CONSTRAINT fk_dispatch_maintainer FOREIGN KEY(maintainer_id) REFERENCES sys_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='派单记录表';
CREATE TABLE repair_record (repair_id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, maintainer_id BIGINT NOT NULL, start_time DATETIME, end_time DATETIME, process_desc TEXT, repair_result VARCHAR(255), unfinished_reason VARCHAR(255), KEY idx_repair_order(order_id), CONSTRAINT fk_repair_order FOREIGN KEY(order_id) REFERENCES repair_order(order_id), CONSTRAINT fk_repair_maintainer FOREIGN KEY(maintainer_id) REFERENCES sys_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='维修记录表';
CREATE TABLE acceptance_record (acceptance_id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, reporter_id BIGINT NOT NULL, accept_result VARCHAR(32) NOT NULL, return_reason VARCHAR(255), accept_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_accept_order(order_id), CONSTRAINT fk_accept_order FOREIGN KEY(order_id) REFERENCES repair_order(order_id), CONSTRAINT fk_accept_reporter FOREIGN KEY(reporter_id) REFERENCES sys_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='验收返修记录表';
CREATE TABLE evaluation_record (evaluation_id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, reporter_id BIGINT NOT NULL, score TINYINT NOT NULL, comment VARCHAR(500), evaluate_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_evaluation_order(order_id), CONSTRAINT fk_evaluation_order FOREIGN KEY(order_id) REFERENCES repair_order(order_id), CONSTRAINT fk_evaluation_reporter FOREIGN KEY(reporter_id) REFERENCES sys_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='评价记录表';
CREATE TABLE order_status_log (log_id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, operator_id BIGINT NOT NULL, old_status VARCHAR(32), new_status VARCHAR(32) NOT NULL, change_reason VARCHAR(255), change_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_status_order(order_id), CONSTRAINT fk_status_order FOREIGN KEY(order_id) REFERENCES repair_order(order_id), CONSTRAINT fk_status_operator FOREIGN KEY(operator_id) REFERENCES sys_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='工单状态流转记录表';
SET FOREIGN_KEY_CHECKS=1;
